// Analyzer config. test_mode=true by default. No external calls here.
function pad(n){return String(n).padStart(2,'0');}
const d=new Date();const now=d.toISOString();
const stamp=d.getFullYear()+pad(d.getMonth()+1)+pad(d.getDate())+'_'+pad(d.getHours())+pad(d.getMinutes())+pad(d.getSeconds());
return [{ json: {
  test_mode:true,
  max_records:12,
  analyze_statuses:['approved','new'],
  production_statuses:['approved'],
  run_id:'touchpoint_'+stamp,
  generated_at:now,
  note:'production: set test_mode=false -> only approved analyzed and irrelevant excluded.'
}}];

// Select records to analyze. dedup_status=unique + approval_status in allowed. In test_mode include
// irrelevant fixtures (they route to skipped_log). No external calls.
function str(v){return v==null?'':String(v).trim();}
function low(v){return str(v).toLowerCase();}
const cfg=$('Set Analyzer Config').first().json;
const test_mode=(cfg.test_mode===true);
const allowed=(test_mode?(cfg.analyze_statuses||['approved','new']):(cfg.production_statuses||['approved'])).map(s=>String(s).toLowerCase());
const include_irrelevant=test_mode;
const max_records=parseInt(cfg.max_records)||12;
const run_id=cfg.run_id||'';
const rows=$('Read raw_market_records').all().map(i=>i.json).filter(Boolean);
const out=[];
for(const r of rows){
  if(!str(r.record_id))continue;
  if(low(r.dedup_status)!=='unique')continue;
  if(!allowed.includes(low(r.approval_status)))continue;
  const rth=low(r.record_type_hint)||'unknown';
  if(rth==='irrelevant'&&!include_irrelevant)continue;
  if(out.length>=max_records)break;
  out.push({ json: {
    record_id:str(r.record_id),
    agent_request_id:str(r.agent_request_id),
    source_type:str(r.source_type),
    platform:str(r.platform),
    source_url:str(r.source_url),
    post_url:str(r.post_url),
    profile_url:str(r.profile_url),
    profile_name:str(r.profile_name),
    author_handle:str(r.author_handle),
    published_at:str(r.published_at),
    region_hint:str(r.region_hint),
    service_hint:str(r.service_hint),
    text_context:str(r.text_context),
    comment_text:str(r.comment_text),
    contact_public:str(r.contact_public),
    record_type_hint:rth,
    touchpoint_type:low(r.touchpoint_type),
    lead_intent_hint:low(r.lead_intent_hint),
    urgency_hint:low(r.urgency_hint),
    lead_temperature:low(r.lead_temperature),
    interest_topic:str(r.interest_topic),
    probable_need:str(r.probable_need),
    is_irrelevant:(rth==='irrelevant'),
    run_id:run_id,
    batch_index:out.length+1
  }});
}
return out;

// Per-record holder (runs once per loop iteration). Builds the analyzer text. No external calls.
function str(v){return v==null?'':String(v).trim();}
const r=$json;
const now=new Date().toISOString();
let combined=str(r.text_context);
if(str(r.comment_text))combined+=' || КОММЕНТАРИЙ: '+str(r.comment_text);
if(str(r.interest_topic))combined+=' || ТЕМА: '+str(r.interest_topic);
if(str(r.probable_need))combined+=' || ВЕРОЯТНАЯ ПОТРЕБНОСТЬ: '+str(r.probable_need);
return [{ json: Object.assign({}, r, { parsed_at:now, analyzer_text:combined.substring(0,3500) }) }];

const response = $json;
const srcRecord = $('Prepare Record').first().json;
function cap(s, n) { return (s == null ? '' : String(s)).substring(0, n); }
function extractBalanced(s) {
  const start = s.indexOf('{');
  if (start === -1) return null;
  let depth = 0, inStr = false, esc = false;
  for (let i = start; i < s.length; i++) {
    const c = s[i];
    if (inStr) { if (esc) { esc = false; } else if (c === '\\') { esc = true; } else if (c === '"') { inStr = false; } continue; }
    if (c === '"') { inStr = true; continue; }
    if (c === '{') depth++;
    else if (c === '}') { depth--; if (depth === 0) return s.substring(start, i + 1); }
  }
  return null;
}
function tryParse(text) {
  let txt = String(text).trim();
  txt = txt.replace(/^```json\s*/i, '').replace(/```\s*$/, '').trim();
  txt = txt.replace(/^```\s*/, '').replace(/```\s*$/, '').trim();
  const norm = (x) => x.replace(/[‘’]/g, "'").replace(/[“”«»]/g, '"');
  try { return { ok: true, obj: JSON.parse(norm(txt)), candidate: cap(txt, 500) }; } catch(e) {}
  const bal = extractBalanced(txt);
  if (bal) { try { return { ok: true, obj: JSON.parse(norm(bal)), candidate: cap(bal, 500) }; } catch(e) {} }
  const s = txt.indexOf('{'), e2 = txt.lastIndexOf('}');
  if (s !== -1 && e2 !== -1 && e2 > s) { const slice = txt.substring(s, e2 + 1); try { return { ok: true, obj: JSON.parse(norm(slice)), candidate: cap(slice, 500) }; } catch(e) {} return { ok: false, candidate: cap(slice, 500) }; }
  return { ok: false, candidate: cap(txt, 500) };
}
function fail(err, prev, summary) {
  return [{ json: {
    parse_ok: false, parse_method: 'primary_json', repair_used: false,
    processing_status: 'technical_error_candidate',
    primary_parse_error: cap(err, 300),
