Unknown text -> "". Unknown score -> 1. Unusable -> status=skipped, entity_type=irrelevant, recommended_action=ignore, all scores=1.
Enums: entity_type[competitor,lead_signal,market_signal,content_idea,irrelevant]; recommended_action[contact,investigate,monitor,create_content,add_to_semantics,ignore]; status[analyzed,skipped]; freshness_status[fresh,recent,old,unknown].`;
const userMsg = JSON.stringify({
  original_record: {
    source_type: srcRecord.source_type || '',
    platform: srcRecord.platform || '',
    source_url: srcRecord.source_url || '',
    profile_url: srcRecord.profile_url || '',
    parsed_at: srcRecord.parsed_at || '',
    published_at: srcRecord.published_at || '',
    text_context: cap(srcRecord.analyzer_text || srcRecord.text_context || '', 500)
  },
  raw_primary_response: rawPreview,
  primary_parse_error: primaryErr
});
return [{ json: {
  model: 'claude-sonnet-4-6',
  max_tokens: 700,
  temperature: 0,
  system: repairSystem,
  messages: [{ role: 'user', content: userMsg }]
}}];

const response = $json;
const primary = $('Parse Primary JSON').first().json;
const src = $('Prepare Record').first().json;
function cap(s, n) { return (s == null ? '' : String(s)).substring(0, n); }
function extractBalanced(s) {
