  txt = txt.replace(/^```\s*/, '').replace(/```\s*$/, '').trim();
  const norm = (x) => x.replace(/[‘’]/g, "'").replace(/[“”«»]/g, '"');
  try { return { ok: true, obj: JSON.parse(norm(txt)) }; } catch(e) {}
