const data = $json;
const src = $('Prepare Record').first().json;
function clamp(v) { const n = parseInt(v); return isNaN(n) ? 1 : Math.min(100, Math.max(1, n)); }
function truncate(s, n) { return (s == null ? '' : String(s)).substring(0, n); }
function cleanContact(raw) {
  const s = String(raw || '').trim();
  if (!s) return '';
  if (/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/.test(s)) return s;
  if (/t\.me\/|wa\.me\//i.test(s)) return s;
  if (/(^|[^A-Za-z0-9_])@[A-Za-z0-9_]{4,}/.test(s)) return s;
  const digits = s.replace(/\D/g, '');
  if (digits.length >= 10 && digits.length <= 11) return s;
  return '';
}
const now = new Date().toISOString();
const run_id = src.run_id || '';
const batch_index = src.batch_index || 0;

// technical_error passthrough from Parse Repaired JSON
if (data.processing_status === 'technical_error' && data.route === 'technical_errors') {
  return [{ json: {
    created_at: now,
    source_type: src.source_type || '',
    platform: src.platform || '',
    source_url: src.source_url || '',
    parsed_at: src.parsed_at || now,
    published_at: src.published_at || '',
    freshness_status: 'unknown',
    entity_type: 'irrelevant',
    company_name: '',
    profile_name: src.profile_name || '',
    profile_url: src.profile_url || '',
    region: src.region_hint || '',
    service_type: 'unknown',
    offer_text: '',
    terms: '',
    contact_public: '',
    text_context: truncate(src.analyzer_text || src.text_context || '', 3500),
    detected_need: '',
    competitor_strength: 1,
    lead_signal_score: 1,
    content_idea_score: 1,
    quality_score: 1,
    reason: 'Claude вернул невалидный JSON и ремонт не удался. Запись отправлена в technical_errors для ручной проверки. Действие: проверить вручную.',
    recommended_action: 'ignore',
    status: 'analyzed',
    processing_status: 'technical_error',
    parse_method: data.parse_method || 'technical_error',
    parse_error: truncate(data.parse_error || '', 800),
    raw_response_preview: truncate(data.raw_response_preview, 500),
    route: 'technical_errors',
