if (safeStatus === 'skipped' || safeEntity === 'irrelevant') {
  route = 'skipped_log'; needsReview = false; procStatus = 'business_skip';
} else if (safeEntity === 'lead_signal' && leadScore >= 70 && safeAction === 'contact' && hasContact) {
  route = 'results'; needsReview = false;
} else if (safeEntity === 'lead_signal') {
  route = 'review_queue'; needsReview = true;
} else if (safeEntity === 'competitor') {
  route = 'monitor_queue'; needsReview = false;
} else if (safeEntity === 'content_idea' || safeEntity === 'market_signal') {
  if (safeAction === 'ignore') { route = 'skipped_log'; needsReview = false; procStatus = 'business_skip'; }
  else { route = 'content_queue'; needsReview = true; }
} else {
  if (safeAction === 'contact') route = 'results';
  else if (safeAction === 'monitor') route = 'monitor_queue';
  else if (safeAction === 'create_content' || safeAction === 'add_to_semantics') route = 'content_queue';
  else if (safeAction === 'ignore') { route = 'skipped_log'; procStatus = 'business_skip'; }
